   332→      {/* Simplex Bezirke toggle (admin only) */}
   333→      {isAdmin && (
   334→        <div className="bg-white rounded-xl shadow p-3 sm:p-4">
   335→          <label className="flex items-center gap-3 cursor-pointer">
   336→            <input
   337→              type="checkbox"
   338→              checked={exercise.simplex_bezirke !== 0}
   339→              onChange={async (e) => {
