   450→                      <input type="text" placeholder="Rufzeichen" value={newRepCallsign} onChange={e => setNewRepCallsign(e.target.value.toUpperCase())} className="border rounded px-2 py-1 text-sm font-mono uppercase w-24" />
   451→                    </div>
