   490→                  </label>
   491→                </div>
   492→              );
   493→            })}
   494→          </div>
   495→
   496→          {/* Add custom simplex */}
   497→          {showAddForm === 'simplex' ? (
   498→            <div className="mt-3 p-3 bg-gray-50 rounded-lg space-y-2">
   499→              <div className="flex gap-2 flex-wrap">
   500→                <input type="text" placeholder="Name (optional)" value={newRepName} onChange={e => setNewRepName(e.target.value)} className="border rounded px-2 py-1 text-sm flex-1 min-w-[120px]" />
   501→                <input type="text" placeholder="Frequenz MHz" value={newRepFreq} onChange={e => setNewRepFreq(e.target.value)} className="border rounded px-2 py-1 text-sm w-28" />
   502→              </div>
   503→              <div className="flex gap-2">
   504→                <button onClick={() => addCustomRepeater(null)} className="bg-[#c8102e] hover:bg-[#a00d24] text-white px-3 py-1 rounded text-sm">Hinzufügen</button>
   505→                <button onClick={() => setShowAddForm(null)} className="text-gray-500 text-sm hover:text-gray-700">Abbrechen</button>
