   510→              + Simplex-Frequenz hinzufügen
   511→            </button>
   512→          )}
   513→        </div>
   514→      </div>
   515→
   516→      {/* Delete confirmation modal */}
   517→      {showDeleteConfirm && (
   518→        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
