   535→              >
   536→                Abbrechen
   537→              </button>
   538→              <button
   539→                onClick={async () => {
   540→                  setDeleting(true);
   541→                  try {
   542→                    await apiFetch(`/api/v1/exercises/${id}`, { method: 'DELETE' });
   543→                    navigate('/');
   544→                  } catch {} finally {
   545→                    setDeleting(false);
