     1→import { useState, useEffect, useCallback, useRef } from 'react';
     2→import { useParams, Link } from 'react-router-dom';
     3→import { apiFetch } from '../services/api';
     4→import { getSocket } from '../services/socket';
     5→import LandMode from '../components/LandMode';
     6→import BundMode from '../components/BundMode';
     7→import RunningTotals from '../components/RunningTotals';
     8→
     9→interface Stats {
    10→  totalParticipants: number;
    11→  totalReports: number;
    12→  perRepeater: { short_name: string; count: number }[];
    13→}
    14→
    15→export default function ExercisePage() {
