   315→                          availableBezirke={repBezirke}
   316→                          onSubmit={(form) => handleBezirkSubmit('??', rep.repeater_id, form)}
   317→                          onEdit={handleEdit}
   318→                          onDelete={handleDelete}
   319→                          onMoveToBezirk={handleMoveToBezirk}
   320→                          editingId={editingId}
   321→                          editForm={editForm}
   322→                          onEditChange={setEditForm}
   323→                          onEditSave={handleUpdate}
   324→                          onEditCancel={() => setEditingId(null)}
   325→                          dragReportId={dragReportId}
   326→                          onDragStart={setDragReportId}
   327→                          onDragEnd={() => setDragReportId(null)}
   328→                        />
   329→                      );
   330→                    })()}
   331→                  </>
   332→                ) : (
   333→                  /* Normal repeater with bezirke */
   334→                  <>
   335→                    {repBezirke.map(bz => {
   336→                      const bzReports = repReports.filter(r => r.bezirk_code === bz.code);
   337→                      return (
   338→                        <BezirkRow
   339→                          key={bz.code}
   340→                          bezirk={bz}
   341→                          reports={bzReports}
   342→                          repeaterId={rep.repeater_id}
   343→                          availableBezirke={repBezirke}
   344→                          onSubmit={(form) => handleBezirkSubmit(bz.code, rep.repeater_id, form)}
   345→                          onEdit={handleEdit}
   346→                          onDelete={handleDelete}
   347→                          onMoveToBezirk={handleMoveToBezirk}
   348→                          editingId={editingId}
   349→                          editForm={editForm}
   350→                          onEditChange={setEditForm}
   351→                          onEditSave={handleUpdate}
   352→                          onEditCancel={() => setEditingId(null)}
   353→                          dragReportId={dragReportId}
   354→                          onDragStart={setDragReportId}
   355→                          onDragEnd={() => setDragReportId(null)}
   356→                        />
   357→                      );
   358→                    })}
   359→                    {/* Sonstige — reports without matching bezirk + entry form */}
   360→                    {(() => {
   361→                      const bzCodes = new Set(repBezirke.map(b => b.code));
   362→                      const unassigned = repReports.filter(r => !r.bezirk_code || !bzCodes.has(r.bezirk_code));
   363→                      return (
   364→                        <BezirkRow
   365→                          bezirk={{ code: '??', name: 'Sonstige', is_capital: false }}
   366→                          reports={unassigned}
   367→                          repeaterId={rep.repeater_id}
   368→                          availableBezirke={repBezirke}
   369→                          onSubmit={(form) => handleBezirkSubmit('??', rep.repeater_id, form)}
   370→                          onEdit={handleEdit}
   371→                          onDelete={handleDelete}
   372→                          onMoveToBezirk={handleMoveToBezirk}
   373→                          editingId={editingId}
   374→                          editForm={editForm}
   375→                          onEditChange={setEditForm}
   376→                          onEditSave={handleUpdate}
   377→                          onEditCancel={() => setEditingId(null)}
   378→                          dragReportId={dragReportId}
   379→                          onDragStart={setDragReportId}
   380→                          onDragEnd={() => setDragReportId(null)}
   381→                        />
   382→                      );
   383→                    })()}
   384→                  </>
   385→                )}
   386→              </>
   387→            ) : (
   388→              /* No Bezirke — flat list with input form */
   389→              <FlatReportRow
   390→                reports={repReports}
   391→                repeaterId={rep.repeater_id}
   392→                onSubmit={(form) => handleBezirkSubmit('', rep.repeater_id, form)}
   393→                onEdit={handleEdit}
   394→                onDelete={handleDelete}
   395→                editingId={editingId}
   396→                editForm={editForm}
   397→                onEditChange={setEditForm}
   398→                onEditSave={handleUpdate}
   399→                onEditCancel={() => setEditingId(null)}
   400→              />
   401→            )}
   402→          </div>
   403→        )}
   404→      </div>
   405→    );
   406→  };
   407→
   408→  return (
   409→    <div className="space-y-2">
   410→      {sortedBlCodes.map(blCode => {
   411→        const blReps = repeatersByBl[blCode];
   412→        const label = BUNDESLAND_NAMES[blCode] || 'Sonstige';
   413→        return (
   414→          <div key={blCode}>
   415→            <div className="px-1 mb-1 mt-2">
   416→              <span className="text-xs font-semibold text-gray-500 uppercase tracking-wide">{label}</span>
   417→            </div>
   418→            <div className="space-y-2">
   419→              {blReps.map(rep => renderRepeaterCard(rep))}
   420→            </div>
   421→          </div>
   422→        );
   423→      })}
   424→
   425→      {simplexRepeaters.length > 0 && (
   426→        <div>
   427→          <div className="px-1 mb-1 mt-2">
   428→            <span className="text-xs font-semibold text-gray-500 uppercase tracking-wide">Simplex</span>
   429→          </div>
   430→          <div className="space-y-2">
   431→            {simplexRepeaters.map(rep => renderRepeaterCard(rep))}
   432→          </div>
   433→        </div>
