   438→
   439→interface BezirkRowProps {
   440→  bezirk: any;
   441→  reports: any[];
   442→  repeaterId: number;
   443→  availableBezirke: any[];
   444→  onSubmit: (form: EntryForm) => void;
   445→  onEdit: (report: any) => void;
   446→  onDelete: (id: number) => void;
   447→  onMoveToBezirk: (reportId: number, bezirkCode: string | null) => void;
   448→  editingId: number | null;
   449→  editForm: EntryForm;
   450→  onEditChange: (form: EntryForm) => void;
   451→  onEditSave: () => void;
   452→  onEditCancel: () => void;
   453→  dragReportId: number | null;
   454→  onDragStart: (reportId: number) => void;
   455→  onDragEnd: () => void;
   456→}
   457→
   458→function BezirkRow({ bezirk, reports, repeaterId, availableBezirke, onSubmit, onEdit, onDelete, onMoveToBezirk, editingId, editForm, onEditChange, onEditSave, onEditCancel, dragReportId, onDragStart, onDragEnd }: BezirkRowProps) {
   459→  const [form, setForm] = useState<EntryForm>({ callsign: '', operator: null, rapport: '5/9', notes: '', opName: '', opQth: '', bezirkCode: '' });
   460→  const [dragOver, setDragOver] = useState(false);
   461→  const callsignRef = useRef<CallsignInputRef>(null);
   462→  const rapportRef = useRef<HTMLInputElement>(null);
   463→
   464→  const handleSubmit = (e: FormEvent) => {
   465→    e.preventDefault();
   466→    if (!form.callsign && !form.operator) return;
   467→    onSubmit(form);
   468→    setForm({ callsign: '', operator: null, rapport: '5/9', notes: '', opName: '', opQth: '', bezirkCode: '' });
   469→    setTimeout(() => callsignRef.current?.focus(), 50);
   470→  };
   471→
   472→  const handleDrop = (e: React.DragEvent) => {
   473→    e.preventDefault();
   474→    setDragOver(false);
   475→    if (dragReportId) {
   476→      const targetCode = bezirk.code === '??' ? null : bezirk.code;
   477→      onMoveToBezirk(dragReportId, targetCode);
   478→    }
   479→  };
   480→
   481→  const saveOperatorField = (field: 'name' | 'qth', value: string) => {
   482→    if (!form.operator?.id) return;
   483→    const original = field === 'name' ? (form.operator.name || '') : (form.operator.qth || '');
   484→    if (value === original) return;
   485→    apiFetch(`/api/v1/operators/${form.operator.id}`, {
   486→      method: 'PATCH',
   487→      body: JSON.stringify({ [field]: value || null }),
   488→    }).then(() => {
   489→      setForm(f => ({ ...f, operator: { ...f.operator, [field]: value || null } }));
   490→    }).catch(() => {});
   491→  };
   492→
   493→  return (
   494→    <div
   495→      className={`px-2 sm:px-3 py-1.5 transition-colors ${dragOver && dragReportId ? 'bg-blue-100 ring-2 ring-blue-400 ring-inset' : ''}`}
   496→      onDragOver={e => { if (dragReportId) { e.preventDefault(); setDragOver(true); } }}
   497→      onDragLeave={() => setDragOver(false)}
   498→      onDrop={handleDrop}
   499→    >
   500→      <div className="flex items-center gap-1.5 sm:gap-2 mb-1">
   501→        <span className={`text-xs font-mono px-1.5 py-0.5 rounded text-white ${bezirk.code === '??' ? 'bg-[#ffc107] text-gray-800' : bezirk.is_capital ? 'bg-[#dc3545]' : 'bg-[#6c757d]'}`}>
   502→          {bezirk.code === '??' ? '??' : bezirk.code}
   503→        </span>
   504→        <span className="text-xs text-gray-500 truncate">{bezirk.name}</span>
   505→        {reports.length > 0 && <span className="text-xs text-gray-400 flex-shrink-0">({reports.length})</span>}
   506→      </div>
   507→
   508→      {reports.length > 0 && (
   509→        <table className="w-full text-xs mb-1">
   510→          <tbody>
   511→            {reports.map((r, idx) => (
   512→              <tr
   513→                key={r.id}
   514→                className={`hover:bg-blue-50 group ${dragReportId === r.id ? 'opacity-40' : ''}`}
   515→                draggable={editingId !== r.id}
   516→                onDragStart={e => { e.dataTransfer.effectAllowed = 'move'; onDragStart(r.id); }}
   517→                onDragEnd={onDragEnd}
   518→              >
   519→                {editingId === r.id ? (
   520→                  <td colSpan={5} className="py-0.5">
   521→                    <div className="flex items-center gap-1 bg-blue-50 rounded p-1 flex-wrap" onKeyDown={e => { if (e.key === 'Enter') { e.preventDefault(); onEditSave(); } }}>
   522→                      <span className="font-mono font-medium">{r.callsign}</span>
   523→                      <input value={editForm.opName} onChange={e => onEditChange({ ...editForm, opName: e.target.value })} placeholder="Name" className="border rounded px-1 py-0.5 text-xs w-16 sm:w-20 hidden sm:block" />
   524→                      <input value={editForm.opQth} onChange={e => onEditChange({ ...editForm, opQth: e.target.value })} placeholder="QTH" className="border rounded px-1 py-0.5 text-xs w-14 sm:w-16 hidden sm:block" />
   525→                      <input value={editForm.rapport} onChange={e => onEditChange({ ...editForm, rapport: e.target.value.toUpperCase() })} className="border rounded px-1 py-0.5 font-mono text-xs w-16 sm:w-20" autoFocus />
   526→                      <input value={editForm.notes} onChange={e => onEditChange({ ...editForm, notes: e.target.value })} placeholder="Sonst." className="border rounded px-1 py-0.5 text-xs w-16 sm:w-20" />
   527→                      <select
   528→                        value={editForm.bezirkCode}
   529→                        onChange={e => onEditChange({ ...editForm, bezirkCode: e.target.value })}
   530→                        className="border rounded px-1 py-0.5 text-xs w-14 sm:w-16"
   531→                        title="Bezirk"
   532→                      >
   533→                        <option value="">??</option>
   534→                        {availableBezirke.map(bz => <option key={bz.code} value={bz.code}>{bz.code}</option>)}
   535→                      </select>
   536→                      <button onClick={onEditSave} className="text-green-600 text-xs font-bold">OK</button>
   537→                      <button onClick={onEditCancel} className="text-gray-400 text-xs">X</button>
   538→                    </div>
   539→                  </td>
   540→                ) : (
   541→                  <>
   542→                    <td className="py-0.5 text-gray-400 w-4 cursor-grab">{idx + 1}</td>
   543→                    <td className="py-0.5 cursor-pointer" onClick={() => onEdit(r)}>
   544→                      <span className="font-mono font-medium">{r.callsign}</span>
   545→                      {r.operator_name && <span className="ml-1 text-gray-500 text-xs">{r.operator_name}</span>}
   546→                      {r.operator_qth && <span className="ml-1 text-gray-400 text-xs hidden sm:inline">{r.operator_qth}</span>}
   547→                    </td>
   548→                    <td className="py-0.5 font-mono text-gray-500 w-16 sm:w-24 cursor-pointer" onClick={() => onEdit(r)}>
   549→                      {r.readability && r.strength ? `${r.readability}/${r.strength}${r.db_over_s9 || ''}` : '—'}
   550→                    </td>
   551→                    <td className="py-0.5 text-gray-500 cursor-pointer hidden sm:table-cell" onClick={() => onEdit(r)}>{r.notes || ''}</td>
   552→                    <td className="py-0.5 w-4">
   553→                      <button onClick={() => onDelete(r.id)} className="text-red-400 hover:text-red-600 opacity-0 group-hover:opacity-100">x</button>
   554→                    </td>
   555→                  </>
   556→                )}
   557→              </tr>
   558→            ))}
   559→          </tbody>
   560→        </table>
   561→      )}
   562→
   563→      <form onSubmit={handleSubmit} className="flex items-center gap-1">
   564→        <CallsignInput
   565→          ref={callsignRef}
   566→          value={form.callsign}
   567→          onChange={v => setForm(f => ({ ...f, callsign: v, operator: null, opName: '', opQth: '' }))}
   568→          onSelect={op => {
   569→            setForm(f => ({ ...f, operator: op, callsign: op.callsign, opName: op.name || '', opQth: op.qth || '' }));
   570→            setTimeout(() => { const el = rapportRef.current; if (el) { el.focus(); el.setSelectionRange(el.value.length, el.value.length); } }, 50);
   571→          }}
   572→          onEnter={() => setTimeout(() => { const el = rapportRef.current; if (el) { el.focus(); el.setSelectionRange(el.value.length, el.value.length); } }, 50)}
   573→          className="w-24 sm:w-28"
   574→        />
   575→        <input
   576→          type="text"
   577→          value={form.opName}
   578→          onChange={e => setForm(f => ({ ...f, opName: e.target.value }))}
   579→          onBlur={e => saveOperatorField('name', e.target.value)}
   580→          placeholder="Name"
   581→          className="border border-gray-300 rounded px-1.5 py-0.5 text-xs w-20 sm:w-24 focus:outline-none focus:ring-1 focus:ring-blue-500 hidden sm:block"
   582→        />
   583→        <input
   584→          type="text"
   585→          value={form.opQth}
   586→          onChange={e => setForm(f => ({ ...f, opQth: e.target.value }))}
   587→          onBlur={e => saveOperatorField('qth', e.target.value)}
   588→          placeholder="QTH"
   589→          className="border border-gray-300 rounded px-1.5 py-0.5 text-xs w-16 sm:w-20 focus:outline-none focus:ring-1 focus:ring-blue-500 hidden sm:block"
   590→        />
   591→        <input
   592→          ref={rapportRef}
   593→          type="text"
   594→          value={form.rapport}
   595→          onChange={e => setForm(f => ({ ...f, rapport: e.target.value.toUpperCase() }))}
   596→          placeholder="5/9"
   597→          className="border border-gray-300 rounded px-1.5 py-0.5 font-mono text-xs w-16 sm:w-20 focus:outline-none focus:ring-1 focus:ring-blue-500"
   598→          onKeyDown={e => {
   599→            if (e.altKey && e.key >= '1' && e.key <= '9') {
   600→              e.preventDefault();
