import type Database from 'better-sqlite3';
import { callsignToCountryCode } from '../utils/callsignCountry.js';

export function runMigrations(db: Database.Database): void {
  db.exec(`
    CREATE TABLE IF NOT EXISTS bundeslaender (
      code TEXT PRIMARY KEY,
      name TEXT NOT NULL,
      sort_order INTEGER,
      is_international INTEGER DEFAULT 0
    );

    CREATE TABLE IF NOT EXISTS bezirke (
      code TEXT PRIMARY KEY,
      name TEXT NOT NULL,
      bundesland_code TEXT REFERENCES bundeslaender(code),
      is_capital INTEGER DEFAULT 0
    );

    CREATE TABLE IF NOT EXISTS operators (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      callsign TEXT UNIQUE NOT NULL,
      name TEXT,
      qth TEXT,
      bezirk_code TEXT REFERENCES bezirke(code),
      bundesland_code TEXT REFERENCES bundeslaender(code),
      is_bos_arsa INTEGER DEFAULT 0,
      is_arena INTEGER DEFAULT 0,
      is_portable INTEGER DEFAULT 0,
      is_exercise_support INTEGER DEFAULT 0,
      gender TEXT,
      email TEXT,
      equipment TEXT,
      antenna TEXT,
      has_emergency_power INTEGER DEFAULT 0,
      has_lighthouse_readiness INTEGER DEFAULT 0,
      latitude REAL,
      longitude REAL,
      created_at TEXT DEFAULT (datetime('now')),
      updated_at TEXT DEFAULT (datetime('now'))
    );

    CREATE TABLE IF NOT EXISTS repeaters (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      short_name TEXT NOT NULL,
      site_name TEXT,
      band TEXT,
      callsign TEXT,
      frequency_mhz REAL,
      offset_mhz REAL,
      ctcss_hz REAL,
      burst_hz REAL,
      type TEXT DEFAULT 'repeater',
      is_linked INTEGER DEFAULT 0,
      sort_order INTEGER,
      bundesland_code TEXT REFERENCES bundeslaender(code),
      is_custom INTEGER DEFAULT 0
    );

    CREATE TABLE IF NOT EXISTS einstiegspunkte (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      repeater_id INTEGER REFERENCES repeaters(id),
      site_name TEXT NOT NULL,
      callsign TEXT,
      abbreviation TEXT,
      bundesland_code TEXT REFERENCES bundeslaender(code),
      sort_order INTEGER
    );

    CREATE TABLE IF NOT EXISTS exercises (
      id TEXT PRIMARY KEY,
      name TEXT,
      date TEXT NOT NULL,
      notes TEXT,
      created_at TEXT DEFAULT (datetime('now'))
    );

    CREATE TABLE IF NOT EXISTS exercise_repeaters (
      exercise_id TEXT REFERENCES exercises(id) ON DELETE CASCADE,
      repeater_id INTEGER REFERENCES repeaters(id),
      operator_callsign TEXT,
      PRIMARY KEY (exercise_id, repeater_id)
    );

    CREATE TABLE IF NOT EXISTS exercise_attendance (
      exercise_id TEXT REFERENCES exercises(id) ON DELETE CASCADE,
      operator_id INTEGER REFERENCES operators(id),
      callsign_suffix TEXT,
      is_present INTEGER DEFAULT 1,
      entered_by TEXT,
      PRIMARY KEY (exercise_id, operator_id)
    );

    CREATE TABLE IF NOT EXISTS signal_reports (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      exercise_id TEXT REFERENCES exercises(id) ON DELETE CASCADE,
      operator_id INTEGER REFERENCES operators(id),
      repeater_id INTEGER REFERENCES repeaters(id),
      readability INTEGER,
      strength INTEGER,
      db_over_s9 TEXT,
      einstiegspunkt_id INTEGER REFERENCES einstiegspunkte(id),
      is_op_marker INTEGER DEFAULT 0,
      notes TEXT,
      entered_by TEXT,
      created_at TEXT DEFAULT (datetime('now')),
      updated_at TEXT DEFAULT (datetime('now')),
      UNIQUE (exercise_id, operator_id, repeater_id)
    );

    CREATE TABLE IF NOT EXISTS admins (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      username TEXT UNIQUE NOT NULL,
      password_hash TEXT NOT NULL,
      role TEXT DEFAULT 'operator'
    );

    CREATE INDEX IF NOT EXISTS idx_operators_callsign ON operators(callsign);
    CREATE INDEX IF NOT EXISTS idx_operators_bundesland ON operators(bundesland_code);
    CREATE INDEX IF NOT EXISTS idx_operators_bezirk ON operators(bezirk_code);
    CREATE INDEX IF NOT EXISTS idx_signal_reports_exercise ON signal_reports(exercise_id);
    CREATE INDEX IF NOT EXISTS idx_signal_reports_operator ON signal_reports(operator_id);
    CREATE INDEX IF NOT EXISTS idx_signal_reports_repeater ON signal_reports(repeater_id);
    CREATE INDEX IF NOT EXISTS idx_exercise_attendance_exercise ON exercise_attendance(exercise_id);
    CREATE INDEX IF NOT EXISTS idx_einstiegspunkte_repeater ON einstiegspunkte(repeater_id);
    CREATE INDEX IF NOT EXISTS idx_bezirke_bundesland ON bezirke(bundesland_code);
  `);

  // Migration: admins table from callsign/pin_hash to username/password_hash
  const adminCols = db.prepare("PRAGMA table_info(admins)").all() as any[];
  if (adminCols.some((c: any) => c.name === 'callsign')) {
    db.exec("DROP TABLE admins");
    db.exec(`CREATE TABLE admins (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      username TEXT UNIQUE NOT NULL,
      password_hash TEXT NOT NULL,
      role TEXT DEFAULT 'operator'
    )`);
  }

  // Migration: convert exercises from INTEGER id to TEXT GUID
  const exCols = db.prepare("PRAGMA table_info(exercises)").all() as any[];
  const idCol = exCols.find((c: any) => c.name === 'id');
  if (idCol && idCol.type === 'INTEGER') {
    // Recreate all exercise-related tables with TEXT exercise_id
    db.exec(`
      CREATE TABLE exercises_new (
        id TEXT PRIMARY KEY,
        name TEXT,
        date TEXT NOT NULL,
        notes TEXT,
        created_at TEXT DEFAULT (datetime('now'))
      );
      CREATE TABLE exercise_repeaters_new (
        exercise_id TEXT REFERENCES exercises_new(id) ON DELETE CASCADE,
        repeater_id INTEGER REFERENCES repeaters(id),
        operator_callsign TEXT,
        PRIMARY KEY (exercise_id, repeater_id)
      );
      CREATE TABLE exercise_attendance_new (
        exercise_id TEXT REFERENCES exercises_new(id) ON DELETE CASCADE,
        operator_id INTEGER REFERENCES operators(id),
        callsign_suffix TEXT,
        is_present INTEGER DEFAULT 1,
        entered_by TEXT,
        PRIMARY KEY (exercise_id, operator_id)
      );
      CREATE TABLE signal_reports_new (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        exercise_id TEXT REFERENCES exercises_new(id) ON DELETE CASCADE,
        operator_id INTEGER REFERENCES operators(id),
        repeater_id INTEGER REFERENCES repeaters(id),
        readability INTEGER,
        strength INTEGER,
        db_over_s9 TEXT,
        einstiegspunkt_id INTEGER REFERENCES einstiegspunkte(id),
        is_op_marker INTEGER DEFAULT 0,
        notes TEXT,
        entered_by TEXT,
        created_at TEXT DEFAULT (datetime('now')),
        updated_at TEXT DEFAULT (datetime('now')),
        UNIQUE (exercise_id, operator_id, repeater_id)
      );

      DROP TABLE IF EXISTS signal_reports;
      DROP TABLE IF EXISTS exercise_attendance;
      DROP TABLE IF EXISTS exercise_repeaters;
      DROP TABLE IF EXISTS exercises;

      ALTER TABLE exercises_new RENAME TO exercises;
      ALTER TABLE exercise_repeaters_new RENAME TO exercise_repeaters;
      ALTER TABLE exercise_attendance_new RENAME TO exercise_attendance;
      ALTER TABLE signal_reports_new RENAME TO signal_reports;
    `);
  }

  // Migrations for existing databases
  const cols = db.prepare("PRAGMA table_info(exercises)").all() as any[];
  if (!cols.some((c: any) => c.name === 'name')) {
    db.exec("ALTER TABLE exercises ADD COLUMN name TEXT");
  }
  if (!cols.some((c: any) => c.name === 'oe_link_enabled')) {
    db.exec("ALTER TABLE exercises ADD COLUMN oe_link_enabled INTEGER DEFAULT 1");
  }
  if (!cols.some((c: any) => c.name === 'organisator')) {
    db.exec("ALTER TABLE exercises ADD COLUMN organisator TEXT");
  }
  if (!cols.some((c: any) => c.name === 'exercise_type')) {
    db.exec("ALTER TABLE exercises ADD COLUMN exercise_type TEXT DEFAULT 'Krisenkommunikationsübung'");
    db.exec("UPDATE exercises SET exercise_type = '80m Notfunk Runde' WHERE name LIKE '%Notfunk%'");
  }
  if (!cols.some((c: any) => c.name === 'simplex_bezirke')) {
    db.exec("ALTER TABLE exercises ADD COLUMN simplex_bezirke INTEGER DEFAULT 0");
  }

  const repCols = db.prepare("PRAGMA table_info(repeaters)").all() as any[];
  if (!repCols.some((c: any) => c.name === 'bundesland_code')) {
    db.exec("ALTER TABLE repeaters ADD COLUMN bundesland_code TEXT REFERENCES bundeslaender(code)");
  }
  if (!repCols.some((c: any) => c.name === 'is_custom')) {
    db.exec("ALTER TABLE repeaters ADD COLUMN is_custom INTEGER DEFAULT 0");
  }

  // Create index after migration ensures column exists
  db.exec("CREATE INDEX IF NOT EXISTS idx_repeaters_bundesland ON repeaters(bundesland_code)");

  // Migration: add bezirk_code to signal_reports (report bezirk != operator home bezirk)
  const srCols = db.prepare("PRAGMA table_info(signal_reports)").all() as any[];
  if (!srCols.some((c: any) => c.name === 'bezirk_code')) {
    db.exec("ALTER TABLE signal_reports ADD COLUMN bezirk_code TEXT REFERENCES bezirke(code)");
    // Backfill from operator's current bezirk_code
    const backfilled = db.prepare(`
      UPDATE signal_reports SET bezirk_code = (
        SELECT o.bezirk_code FROM operators o WHERE o.id = signal_reports.operator_id
      ) WHERE bezirk_code IS NULL
    `).run();
    console.log(`  Migration: added bezirk_code to signal_reports, backfilled ${backfilled.changes} rows`);
    db.exec("CREATE INDEX IF NOT EXISTS idx_signal_reports_bezirk ON signal_reports(bezirk_code)");
  }

  // Migration: auto-assign bezirk_code for operators in single-bezirk Bundesländer (e.g. Wien → 'W')
  const singleBzBls = db.prepare("SELECT bundesland_code, code FROM bezirke GROUP BY bundesland_code HAVING COUNT(*) = 1").all() as { bundesland_code: string; code: string }[];
  for (const { bundesland_code, code } of singleBzBls) {
    db.prepare("UPDATE operators SET bezirk_code = ? WHERE bundesland_code = ? AND bezirk_code IS NULL").run(code, bundesland_code);
  }
  // Backfill signal_reports bezirk_code from operator where null
  db.prepare(`
    UPDATE signal_reports SET bezirk_code = (
      SELECT o.bezirk_code FROM operators o WHERE o.id = signal_reports.operator_id
    ) WHERE bezirk_code IS NULL AND EXISTS (
      SELECT 1 FROM operators o WHERE o.id = signal_reports.operator_id AND o.bezirk_code IS NOT NULL
    )
  `).run();

  // Migration: backfill operators with null bundesland_code using callsign prefix
  const nullBlOps = db.prepare("SELECT id, callsign FROM operators WHERE bundesland_code IS NULL").all() as { id: number; callsign: string }[];
  if (nullBlOps.length > 0) {
    const updateBl = db.prepare("UPDATE operators SET bundesland_code = ? WHERE id = ?");
    const backfill = db.transaction(() => {
      for (const op of nullBlOps) {
        const code = callsignToCountryCode(op.callsign);
        if (code) updateBl.run(code, op.id);
      }
    });
    backfill();
    if (nullBlOps.length > 0) console.log(`  Migration: backfilled bundesland_code for ${nullBlOps.length} operators`);
  }
}

import { Router } from 'express';
import { randomUUID } from 'crypto';
import { getDb } from '../db/database.js';
import { AuthRequest, requireRole } from '../middleware/auth.js';

export const exercisesRouter = Router();

// List all exercises with summary stats
exercisesRouter.get('/', (_req, res) => {
  const db = getDb();
  const exercises = db.prepare(`
    SELECT e.id, e.date, e.name, e.notes, e.oe_link_enabled, e.exercise_type, e.simplex_bezirke,
      (SELECT COUNT(DISTINCT operator_id) FROM signal_reports WHERE exercise_id = e.id AND is_op_marker = 0) as participant_count,
      (SELECT COUNT(*) FROM signal_reports WHERE exercise_id = e.id AND is_op_marker = 0 AND readability IS NOT NULL) as report_count
    FROM exercises e ORDER BY e.date ASC
  `).all();
  res.json(exercises);
});

// Create exercise (admin only)
exercisesRouter.post('/', requireRole('admin'), (req, res) => {
  const { date, name, oe_link_enabled, exercise_type, simplex_bezirke } = req.body;
  if (!date || !name) {
    res.status(400).json({ error: 'Datum und Name erforderlich' });
    return;
  }
  const db = getDb();
  const id = randomUUID();
  db.prepare('INSERT INTO exercises (id, date, name, oe_link_enabled, exercise_type, simplex_bezirke) VALUES (?, ?, ?, ?, ?, ?)').run(id, date, name, oe_link_enabled !== undefined ? (oe_link_enabled ? 1 : 0) : 1, exercise_type || 'Krisenkommunikationsübung', simplex_bezirke ? 1 : 0);
  const exercise = db.prepare('SELECT * FROM exercises WHERE id = ?').get(id);
  res.status(201).json(exercise);
});

// Get full exercise with reports
exercisesRouter.get('/:id', (req, res) => {
  const db = getDb();
  const exercise = db.prepare('SELECT * FROM exercises WHERE id = ?').get(req.params.id);
  if (!exercise) {
    res.status(404).json({ error: 'Übung nicht gefunden' });
    return;
  }

  const repeaters = db.prepare(`
    SELECT er.*, r.short_name, r.site_name, r.band, r.callsign as repeater_callsign,
      r.frequency_mhz, r.offset_mhz, r.ctcss_hz, r.burst_hz, r.type, r.is_linked,
      r.bundesland_code, bl.name as bundesland_name
    FROM exercise_repeaters er
    JOIN repeaters r ON r.id = er.repeater_id
    LEFT JOIN bundeslaender bl ON bl.code = r.bundesland_code
    WHERE er.exercise_id = ?
    ORDER BY r.bundesland_code, r.sort_order
  `).all(req.params.id);

  const reports = db.prepare(`
    SELECT sr.*, o.callsign, o.name as operator_name, o.qth as operator_qth, sr.bezirk_code, o.bundesland_code,
      r.short_name as repeater_name, r.bundesland_code as repeater_bundesland_code, r.is_linked as repeater_is_linked,
      ep.abbreviation as einstiegspunkt_abbr, ep.site_name as einstiegspunkt_name
    FROM signal_reports sr
    JOIN operators o ON o.id = sr.operator_id
    JOIN repeaters r ON r.id = sr.repeater_id
    LEFT JOIN einstiegspunkte ep ON ep.id = sr.einstiegspunkt_id
    WHERE sr.exercise_id = ?
    ORDER BY r.bundesland_code, o.callsign
  `).all(req.params.id);

  const attendance = db.prepare(`
    SELECT ea.*, o.callsign, o.name as operator_name, o.bezirk_code, o.bundesland_code
    FROM exercise_attendance ea
    JOIN operators o ON o.id = ea.operator_id
    WHERE ea.exercise_id = ?
    ORDER BY o.callsign
  `).all(req.params.id);

  res.json({ ...exercise, repeaters, reports, attendance });
});

// Update exercise notes/name (admin only)
exercisesRouter.patch('/:id', requireRole('admin'), (req, res) => {
  const db = getDb();
  const { notes, name, oe_link_enabled, organisator, exercise_type, simplex_bezirke } = req.body;
  const updates: string[] = [];
  const params: any[] = [];
  if (notes !== undefined) { updates.push('notes = ?'); params.push(notes); }
  if (name !== undefined) { updates.push('name = ?'); params.push(name); }
  if (oe_link_enabled !== undefined) { updates.push('oe_link_enabled = ?'); params.push(oe_link_enabled ? 1 : 0); }
  if (organisator !== undefined) { updates.push('organisator = ?'); params.push(organisator || null); }
  if (exercise_type !== undefined) { updates.push('exercise_type = ?'); params.push(exercise_type); }
  if (simplex_bezirke !== undefined) { updates.push('simplex_bezirke = ?'); params.push(simplex_bezirke ? 1 : 0); }
  if (updates.length === 0) {
    res.status(400).json({ error: 'Keine Änderungen' });
    return;
  }
  params.push(req.params.id);
  db.prepare(`UPDATE exercises SET ${updates.join(', ')} WHERE id = ?`).run(...params);
  const exercise = db.prepare('SELECT * FROM exercises WHERE id = ?').get(req.params.id);
  res.json(exercise);
});

// Delete exercise (admin only)
exercisesRouter.delete('/:id', requireRole('admin'), (req, res) => {
  const db = getDb();
  const exercise = db.prepare('SELECT id, name, date FROM exercises WHERE id = ?').get(req.params.id);
  if (!exercise) {
    res.status(404).json({ error: 'Übung nicht gefunden' });
    return;
  }
  const deleteAll = db.transaction(() => {
    db.prepare('DELETE FROM signal_reports WHERE exercise_id = ?').run(req.params.id);
    db.prepare('DELETE FROM exercise_attendance WHERE exercise_id = ?').run(req.params.id);
    db.prepare('DELETE FROM exercise_repeaters WHERE exercise_id = ?').run(req.params.id);
    db.prepare('DELETE FROM exercises WHERE id = ?').run(req.params.id);
  });
  deleteAll();
  res.json({ success: true });
});

// Get exercise stats
exercisesRouter.get('/:id/stats', (req, res) => {
  const db = getDb();
  const eid = req.params.id;
  const totalParticipants = (db.prepare('SELECT COUNT(DISTINCT operator_id) as c FROM signal_reports WHERE exercise_id = ? AND is_op_marker = 0').get(eid) as any)?.c || 0;
  const totalReports = (db.prepare('SELECT COUNT(*) as c FROM signal_reports WHERE exercise_id = ? AND is_op_marker = 0 AND readability IS NOT NULL').get(eid) as any)?.c || 0;
  const perRepeater = db.prepare(`
    SELECT r.short_name, COUNT(*) as count
    FROM signal_reports sr
    JOIN repeaters r ON r.id = sr.repeater_id
    WHERE sr.exercise_id = ? AND sr.is_op_marker = 0 AND sr.readability IS NOT NULL
    GROUP BY sr.repeater_id
    ORDER BY r.sort_order
  `).all(eid);

  // Bezirk breakdown: participants + reports per bezirk, grouped by bundesland
  const bezirkStats = db.prepare(`
    SELECT bl.name as bundesland, bl.code as bundesland_code, bl.sort_order as bl_sort,
      bz.code as bezirk_code, bz.name as bezirk_name, bz.is_capital,
      COUNT(DISTINCT sr.operator_id) as participants,
      COUNT(CASE WHEN sr.readability IS NOT NULL THEN 1 END) as reports
    FROM signal_reports sr
    JOIN bezirke bz ON bz.code = sr.bezirk_code
    JOIN bundeslaender bl ON bl.code = bz.bundesland_code
    WHERE sr.exercise_id = ? AND sr.is_op_marker = 0
    GROUP BY bz.code
    ORDER BY bl.sort_order, bz.code
  `).all(eid);

  // Bundesland breakdown
  const blStats = db.prepare(`
    SELECT
      COALESCE(bl.name, 'Sonstige') as bundesland,
      o.bundesland_code,
      COUNT(DISTINCT sr.operator_id) as participants,
      COUNT(CASE WHEN sr.readability IS NOT NULL THEN 1 END) as reports
    FROM signal_reports sr
    JOIN operators o ON o.id = sr.operator_id
    LEFT JOIN bundeslaender bl ON bl.code = o.bundesland_code
    WHERE sr.exercise_id = ? AND sr.is_op_marker = 0
    GROUP BY o.bundesland_code
    ORDER BY o.bundesland_code
  `).all(eid);

  // Participant list: all operators with their report counts
  const participants = db.prepare(`
    SELECT o.callsign, o.name, o.bezirk_code, o.bundesland_code,
      bl.name as bundesland_name,
      COUNT(CASE WHEN sr.readability IS NOT NULL THEN 1 END) as report_count
    FROM signal_reports sr
    JOIN operators o ON o.id = sr.operator_id
    LEFT JOIN bundeslaender bl ON bl.code = o.bundesland_code
    WHERE sr.exercise_id = ? AND sr.is_op_marker = 0
    GROUP BY sr.operator_id
    ORDER BY bl.sort_order, o.bezirk_code, o.callsign
  `).all(eid);

  res.json({ totalParticipants, totalReports, perRepeater, bezirkStats, blStats, participants });
});

