        <span className="font-semibold text-[#1e3a5f] text-sm sm:text-base">Simplex Bezirke aktivieren</span>
        <p className="text-xs text-gray-500">Simplex-Frequenzen nach Bundesland und Bezirk gruppieren</p>
      </div>
    </label>
  </div>
)}

