        <button type="submit" title="Rapport speichern (Enter)" className="bg-[#c8102e] hover:bg-[#a00d24] text-white px-2 py-0.5 rounded text-xs flex-shrink-0">
          + ↵
        </button>
      </form>
    </div>
  );
}

